,"seq","occurredAt","entry"],"properties":{"kind":{"const":"vaultUpserted"},"seq":{"type":"integer","minimum":1},"occurredAt":{"type":"string","format":"date-time"},"entry":{"\$ref":"#/\$defs/VaultEntry"}}},"VaultEntry":{"title":"VaultEntry","type":"object","additionalProperties":false,"required":["id","contextId","targets","label","secretKind","createdAt","updatedAt","version"],"properties":{"id":{"type":"string","minLength":1,"description":"Opaque vault-maintainer-assigned identifier for the entry. ULID/UUID/base32 are common; the wire spec only requires non-empty string equality."},"contextId":{"type":"string","minLength":1,"description":"Identifier of the trust context (persona) the entry belongs to. Opaque string interpreted by the vault maintainer; corresponds to a single ContextRecord on the VTA side."},"targets":{"type":"array","minItems":1,"items":{"\$ref":"#/\$defs/SiteTarget"},"description":"One or more binding targets — web origins, mobile app identifiers, and/or DIDs — that this credential applies to. A request from any matching target uses this entry. A typical entry for a service that exists as both a website and mobile apps will list a web origin, an iOS bundle id, and an Android package id; passkeys for that service typically list only the origin (because iOS Associated Domains and Android Asset Links bind apps to the domain at the OS level)."},"label":{"type":"string","minLength":1,"maxLength":256,"description":"Human-readable display name (e.g. \\"Work GitHub\\", \\"Personal bank — checking\\"). Bounded on the wire at 256 characters; a maintainer MAY enforce a shorter limit."},"secretKind":{"\$ref":"#/\$defs/SecretKind","description":"Discriminator for the kind of secret this entry holds. The secret material itself is NEVER returned in metadata views; the kind is exposed so consumers can render an appropriate UI affordance and so policy decisions can route by kind."},"tags":{"type":"array","items":{"type":"string","minLength":1,"maxLength":64},"uniqueItems":true,"description":"User-defined tags for organisation and filtering (e.g. [\\"family\\", \\"finance\\"]). Maintainers MAY enforce a maximum count; the wire spec does not."},"notes":{"type":"string","maxLength":4096,"description":"Non-sensitive notes the user attached to the entry. Visible in metadata view (suitable for support contact, account number, expiry policy memos). SENSITIVE notes belong in the secret payload as a `secureNotes` field — those are only released by vault/release/0.1."},"favicon":{"type":"string","format":"uri","description":"Optional URI of an icon to display in the consumer UI. Maintainers MAY fetch and cache; consumers SHOULD treat as untrusted content and fetch via a sandboxed pipeline."},"selectors":{"type":"array","items":{"type":"string","minLength":1},"uniqueItems":true,"description":"Opaque maintainer-defined selector strings fed to the policy engine when this entry is requested (e.g. \\"recent_uv_required\\", \\"network_class=corp\\", \\"step_up_push\\"). Consumers MUST treat selectors as opaque; they exist for policy authoring on the maintainer side."},"customFieldNames":{"type":"array","items":{"type":"string","minLength":1,"maxLength":128},"uniqueItems":true,"description":"Names of additional fields the user has attached (e.g. [\\"security-question-1\\", \\"account-number\\"]). The VALUES live in the secret payload and are only delivered by vault/release/0.1. Exposing names in metadata lets the consumer render the right form layout before requesting release."},"attachments":{"type":"array","items":{"\$ref":"#/\$defs/AttachmentRef"},"description":"References to encrypted blobs associated with the entry (recovery codes, PEM files, screenshots of authenticator setup). The blobs themselves are fetched via a separate mechanism the maintainer documents; metadata view exposes only the descriptor."},"expiresAt":{"type":"string","format":"date-time","description":"Optional time after which the credential is no longer expected to 